package mz.bam.seeky.android;
import java.io.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Streaming UTF-8 TXT/CSV/TSV/USFM import. No Bible translation is distributed by Seeky. */
final class BibleText {
 interface Sink{void verse(String book,int chapter,int verse,String text)throws Exception;}
 static List<String> csv(String line,char delimiter)throws IOException{List<String> out=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quoted=false;for(int i=0;i<line.length();i++){char c=line.charAt(i);if(c=='"'){if(quoted&&i+1<line.length()&&line.charAt(i+1)=='"'){cell.append('"');i++;}else quoted=!quoted;}else if(c==delimiter&&!quoted){out.add(cell.toString().trim());cell.setLength(0);}else cell.append(c);}if(quoted)throw new IOException("Aspas CSV não fechadas.");out.add(cell.toString().trim());return out;}
 static String code(String code){String[] codes={"GEN","EXO","LEV","NUM","DEU","JOS","JDG","RUT","1SA","2SA","1KI","2KI","1CH","2CH","EZR","NEH","TOB","JDT","EST","1MA","2MA","JOB","PSA","PRO","ECC","SNG","WIS","SIR","ISA","JER","LAM","BAR","EZK","DAN","HOS","JOL","AMO","OBA","JON","MIC","NAM","HAB","ZEP","HAG","ZEC","MAL","MAT","MRK","LUK","JHN","ACT","ROM","1CO","2CO","GAL","EPH","PHP","COL","1TH","2TH","1TI","2TI","TIT","PHM","HEB","JAS","1PE","2PE","1JN","2JN","3JN","JUD","REV"};String[] books={"Genesis","Exodo","Levitico","Numeros","Deuteronomio","Josue","Juizes","Rute","1 Samuel","2 Samuel","1 Reis","2 Reis","1 Cronicas","2 Cronicas","Esdras","Neemias","Tobias","Judite","Ester","1 Macabeus","2 Macabeus","Jó","Salmos","Proverbios","Eclesiastes","Cantares","Sabedoria","Eclesiastico","Isaias","Jeremias","Lamentacoes","Baruque","Ezequiel","Daniel","Oseias","Joel","Amos","Obadias","Jonas","Miqueias","Naum","Habacuque","Sofonias","Ageu","Zacarias","Malaquias","Mateus","Marcos","Lucas","Joao","Atos","Romanos","1 Corintios","2 Corintios","Galatas","Efesios","Filipenses","Colossenses","1 Tessalonicenses","2 Tessalonicenses","1 Timoteo","2 Timoteo","Tito","Filemom","Hebreus","Tiago","1 Pedro","2 Pedro","1 Joao","2 Joao","3 Joao","Judas","Apocalipse"};for(int i=0;i<codes.length;i++)if(codes[i].equalsIgnoreCase(code))return BibleReferences.canonical(books[i]);return BibleReferences.canonical(code);}
 static char delimiter(String line){for(char separator:new char[]{'\t',',',';'}){int at=line.indexOf(separator);if(at>0){String first=line.substring(0,at).trim();if(first.startsWith("\"")&&first.endsWith("\""))first=first.substring(1,first.length()-1);if(!code(first).isEmpty())return separator;}}return 0;}
 static boolean unclosed(String line){boolean quoted=false;for(int i=0;i<line.length();i++)if(line.charAt(i)=='"'){if(quoted&&i+1<line.length()&&line.charAt(i+1)=='"')i++;else quoted=!quoted;}return quoted;}
 static String clean(String text){return text.replaceAll("(?s)\\\\f .*?\\\\f\\*","").replaceAll("\\\\[a-zA-Z0-9]+\\*?","").trim();}
 static int parse(Reader reader,Sink sink,BooleanSupplier cancelled)throws Exception{BufferedReader in=new BufferedReader(reader);String line,book="",pending="",pendingBook="";int chapter=0,verse=0,pendingChapter=0,pendingVerse=0,count=0,number=0;boolean usfm=false;char csvSeparator=0;BiblePlainText prose=null;
  while((line=in.readLine())!=null){if(cancelled.getAsBoolean())throw new InterruptedIOException();number++;if(count>200000)throw new IOException("A Bíblia excede 200000 versículos.");if(line.length()>65536)throw new IOException("Linha demasiado longa: "+number);line=line.replace("\ufeff","").trim();if(line.isEmpty())continue;if(number==1&&line.matches("(?iu)^(?:livro|book)[,;\\t].*"))continue;
   if(line.startsWith("\\id ")){if(pendingVerse>0){if(emit(sink,pendingBook,pendingChapter,pendingVerse,pending))count++;pending="";pendingVerse=0;}usfm=true;book=code(line.substring(4).trim().split("\\s+")[0]);chapter=0;if(book.isEmpty())throw new IOException("Livro USFM desconhecido na linha "+number);continue;}
   if(usfm){if(line.startsWith("\\c ")){if(pendingVerse>0){if(emit(sink,pendingBook,pendingChapter,pendingVerse,pending))count++;pending="";pendingVerse=0;}chapter=Integer.parseInt(line.substring(3).trim().split("\\s+")[0]);}else if(line.startsWith("\\v ")){if(pendingVerse>0){if(emit(sink,pendingBook,pendingChapter,pendingVerse,pending))count++;}String[] split=line.substring(3).trim().split("\\s+",2);verse=Integer.parseInt(split[0]);pendingBook=book;pendingChapter=chapter;pendingVerse=verse;pending=split.length==2?clean(split[1]):"";}else if(pendingVerse>0&&!line.matches("^\\\\(?:h|toc[0-9]?|s[0-9]?|mt[0-9]?|r)\\b.*")){String text=clean(line);if(!text.isEmpty()){if(pending.length()+text.length()>16000)throw new IOException("Versículo acima do limite de texto na linha "+number);pending+=" "+text;}}continue;}
   if(csvSeparator!=0){List<BibleReferences.Reference> explicit=BibleReferences.references(line.substring(0,Math.min(200,line.length())));if(!explicit.isEmpty()&&explicit.get(0).start==0)csvSeparator=0;}
   char detected=delimiter(line);char delimiter=detected!=0?detected:csvSeparator;if(delimiter!=0)csvSeparator=delimiter;List<String> fields=null;if(delimiter!=0){while(unclosed(line)){String next=in.readLine();if(next==null||line.length()+next.length()>65536)throw new IOException("CSV inválido na linha "+number);number++;line+="\n"+next;}fields=csv(line,delimiter);}
   if(fields!=null&&fields.size()>=4){String b=code(fields.get(0));if(b.isEmpty()&&number==1)continue;if(!b.isEmpty()&&fields.get(1).matches("[0-9]{1,3}")&&fields.get(2).matches("[0-9]{1,3}")){StringBuilder value=new StringBuilder(fields.get(3));for(int i=4;i<fields.size();i++)value.append(',').append(fields.get(i));if(emit(sink,b,Integer.parseInt(fields.get(1)),Integer.parseInt(fields.get(2)),value.toString()))count++;continue;}}
   if(fields!=null)throw new IOException("CSV inválido na linha "+number);
   if(prose==null)prose=new BiblePlainText(sink);
   prose.feed(line,cancelled);

   if(count>200000)throw new IOException("A Bíblia excede 200000 versículos.");
  }if(pendingVerse>0){if(emit(sink,pendingBook,pendingChapter,pendingVerse,pending))count++;}if(prose!=null){prose.flush();count+=prose.count;}if(count==0)throw new IOException("Nenhum versículo reconhecido. Verifique os nomes dos livros, capítulos e números de versículos.");return count;
 }
 /** Stores one verse; returns false for an empty verse, which is skipped: paraphrases such as
  *  A Mensagem join verses (Génesis 1:1-2) and leave the second one without text. Wrong numbers
  *  or an oversized verse still stop the import. */
 static boolean emit(Sink sink,String book,int chapter,int verse,String text)throws Exception{if(book.isEmpty()||chapter<1||chapter>999||verse<1||verse>999||(text!=null&&text.length()>16000))throw new IOException("Versículo inválido: "+book+" "+chapter+":"+verse);if(text==null||text.trim().isEmpty())return false;sink.verse(book,chapter,verse,text.trim());return true;}
 private BibleText(){}
}
